settings.custom_css:
selector { position: relative; }
body:not(.elementor-editor-active) selector { display: grid !important; }
body:not(.elementor-editor-active) selector > .mk-slide { grid-area: 1 / 1; opacity: 0; visibility: hidden; transition: opacity 600ms ease, visibility 0s linear 600ms; }
body:not(.elementor-editor-active) selector > .mk-slide.is-activa { opacity: 1; visibility: visible; transition-delay: 0s; }
body:not(.elementor-editor-active) selector > .elementor-widget-html { grid-area: 1 / 1; align-self: end; z-index: 2; pointer-events: none; }

/* Velo: banda plana en la mitad de abajo; en tablet y celular, sobre toda la foto */
@media (max-width: 1200px) {
  selector::before { background: rgba(20,10,31,.6) !important; opacity: 1 !important; }
}
@media (min-width: 1201px) {
  selector { min-height: clamp(640px, calc(100svh - 80px), 860px); }
}

selector .elementor-button { display: inline-flex; align-items: center; gap: 10px; min-height: 56px; padding: 0 24px; border-radius: 0; transition: background-color .15s, color .15s; }
selector .elementor-button:hover, selector .elementor-button:focus { background-color: #FFFFFF; color: #231B2B; }
selector .elementor-button:focus-visible { outline: 3px solid #FFFFFF; outline-offset: 3px; }
selector .elementor-button-content-wrapper { align-items: center; }
selector .elementor-button-text::after { content: "↗"; display: inline-block; margin-left: 10px; transition: transform .15s; }
selector .elementor-button:hover .elementor-button-text::after { transform: translate(3px, -3px); }
@media (max-width: 767px) { selector .elementor-button { min-height: 50px; padding: 0 18px; } }
selector .mk-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }

